const out = [];
String($vars.SUCURSALES || 'COM:Santa Cruz').split('|').forEach(par => {
  const i = par.indexOf(':');
  const cod = (i >= 0 ? par.slice(0, i) : par).trim().toUpperCase();
  const nom = (i >= 0 ? par.slice(i + 1) : '').trim() || cod;
  if (!cod) return;
  const maestroId = (cod === 'COM')
    ? $vars.SHEET_ID_MAESTRO
    : ($vars['MAESTRO_' + cod] || $vars.SHEET_ID_MAESTRO);
  out.push({ json: { sucursal_codigo: cod, sucursal_nombre: nom, maestro_id: maestroId } });
});
return out;

// La sucursal del lote actual viene emparejada 1:1 desde el Loop
const meta = $('Loop sucursales').item.json;

// 'Leer FE2' acaba de leer ESTE maestro; su salida es la entrada directa de este nodo.
// Tomamos la primera fila de datos (fila 2 del sheet) y la columna 'FE' (celda FE2).
const fila = $input.item.json || {};
let raw = (fila.FE !== undefined && fila.FE !== null) ? String(fila.FE).trim() : '';

function parseDMY(s) {
  const m = String(s).trim().match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (!m) return null;
  let [_, d, mo, y] = m;
  d=+d; mo=+mo; y=+y; if(y<100) y+=2000;
  const dt = new Date(y, mo-1, d);
  return isNaN(dt.getTime()) ? null : dt;
}

const hoyStr = $now.toFormat('dd/MM/yyyy');
const hoy = parseDMY(hoyStr);
const feDate = parseDMY(raw);
const soloFecha = dt => dt ? new Date(dt.getFullYear(), dt.getMonth(), dt.getDate()).getTime() : null;

let desactualizada = false;
let motivo = '';
if (!feDate) {
  desactualizada = true;
  motivo = raw ? `formato no reconocido ("${raw}")` : 'celda FE2 vacía';
} else if (soloFecha(feDate) < soloFecha(hoy)) {
  desactualizada = true;
  motivo = `tiene fecha ${raw} (debería ser ${hoyStr})`;
}

return [{ json: { ...meta, fe2_valor: raw, fe2_hoy: hoyStr, desactualizada, motivo } }];

// Todas las sucursales verificadas vienen del nodo previo (aggregate)
const sucs = $('Verificar fecha vs hoy').all().map(i => i.json);
const autorizados = $('Leer autorizados').all().map(i => i.json);

const desfasadas = sucs.filter(s => s.desactualizada);
if (desfasadas.length === 0) return [];

const porSuc = {};
for (const s of desfasadas) porSuc[s.sucursal_codigo] = s;

const lineaSuc = s => `   • *${s.sucursal_nombre}*: ${s.motivo}`;

let textoAdmin = '⚠️ *REVISAR LAS LIQUIDACIONES DE HOY*\n\n';
textoAdmin += `Hola, me fijé la tabla y vi que hay una fecha antigüa no coincide con hoy en:\n\n`;
textoAdmin += desfasadas.map(lineaSuc).join('\n');
textoAdmin += `\n\n_Por favor actualizar las liquidaciones de cada sucursal indicada._`;

const out = [];
for (const a of autorizados) {
  const tipo = String(a.tipo || '').trim().toUpperCase();
  const phone = String(a.phone || '').trim();
  if (!phone) continue;

  if (tipo === 'ADMIN') {
    out.push({ json: { phone, texto: textoAdmin, rol: 'ADMIN' } });
  } else if (tipo === 'CAJERO') {
    const suc = String(a.sucursal || '').trim().toUpperCase();
    const info = porSuc[suc];
    if (info) {
      let t = '⚠️ *¿CARGASTE LAS LIQUIDACIONES?*\n\n';
      t += `Sucursal *${info.sucursal_nombre}* — *${$now.toFormat('dd/MM/yyyy')}*\n\n`;
      t += `La tabla de liquidaciones ${info.motivo}.\n\n`;
      t += `_Por favor actualizar las liquidaciones de hoy._`;
      out.push({ json: { phone, texto: t, rol: 'CAJERO', sucursal: suc } });
    }
  }
}
return out;
